public abstract record Node;
public sealed record Leaf(string Text) : Node;
public sealed record Branch(ImmutableList<Node> Kids) : Node;

public sealed record Frame(Node Parent, int Index);           // one hole per level
public sealed record Loc(Node Focus, ImmutableList<Frame> Path);
public static Loc Up(Loc l)                                    // rebuild the parent once
{
    var f = l.Path[^1];
    if (f.Parent is not Branch b) throw new InvalidOperationException("at root");
    return new Loc(b with { Kids = b.Kids.SetItem(f.Index, l.Focus) }, l.Path.RemoveAt(l.Path.Count - 1));
}
